#include "stdlib/stats/base/dists/burr-type3/mode.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/pow.h"

/**
* Returns the mode of a Burr (type III) distribution with first shape parameter `c` and second shape parameter `d`.
*
* @param c    first shape parameter
* @param d    second shape parameter
* @return     mode
*
* @example
* double v = stdlib_base_dists_burr_type3_mode( 2.0, 1.0 );
* // returns ~0.577
*/
double stdlib_base_dists_burr_type3_mode( const double c, const double d ) {
	if (
		stdlib_base_is_nan( c ) ||
		stdlib_base_is_nan( d ) ||
		c <= 0.0 ||
		d <= 0.0
	) {
		return 0.0 / 0.0; // NaN
	}
	if ( c * d <= 1.0 ) {
		return 0.0;
	}
	return stdlib_base_pow( ( ( c * d ) - 1.0 ) / ( c + 1.0 ), 1.0 / c );
}
